(function(){'use strict';
/* JAH The Physical Chemistry Signature generator — jahdb-physical-chemistry-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-PHYCHS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Physical Chemistry", "desc": "Physical chemistry applies physics to chemical systems: thermodynamics predicts whether reactions can happen, kinetics predicts how fast, quantum mechanics describes electrons and bonds, and statistical mechanics connects molecular behavior to bulk properties.\nIt is the most mathematical branch of chemistry - and the most fundamental. Spectroscopists, electrochemists, and materials scientists all speak its language: energy, entropy, rates, and quantum states.", "how": "Attack problems with the right pillar: energy bookkeeping (thermodynamics), time dependence (kinetics), electronic structure (quantum), or molecular-to-bulk (statistical mechanics). Define the system and surroundings first - every thermodynamic statement needs that boundary.", "keys": ["Four pillars: thermo, kinetics, quantum, statistical mechanics.", "Thermodynamics: can it happen; kinetics: how fast.", "The most mathematical - and most fundamental - branch.", "System vs surroundings defined first, always.", "Underpins spectroscopy, electrochemistry, materials."], "reqs": ["System/surroundings definition.", "Correct pillar for the question.", "Consistent units (SI)."], "stds": ["SI units; energies in J or kJ/mol.", "Standard states specified."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA, Simon JD. Physical Chemistry. University Science; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Pillar picker for physical-chemistry questions.\"\"\"\nqs = {\"will it react?\": \"thermodynamics\", \"how fast?\": \"kinetics\", \"where are electrons?\": \"quantum\", \"why this heat capacity?\": \"statistical mechanics\"}\nfor q, pillar in qs.items():\n    print(f\"  {q:24s} -> {pillar}\")\n"}, {"tier": "Foundations", "g": "Gases", "title": "The Gas Laws and Ideal Gases", "desc": "Boyle (P∝1/V), Charles (V∝T), Avogadro (V∝n) combine into PV = nRT - the ideal gas law, with R = 8.314 J/mol·K. It predicts gas behavior at low pressure and high temperature, where molecules are far apart.\nDalton's law adds partial pressures (P_total = ΣP_i); Graham's law says effusion rate ∝ 1/√M - how uranium isotopes were separated. The ideal gas is a model; its failures motivate real-gas corrections.", "how": "Apply PV = nRT with consistent units (Pa, m³, mol, K). Use Dalton for mixtures (mole fractions × total P). Check ideality: near 1 atm and room T it works; near condensation it fails. Convert units first - most gas-law errors are unit errors.", "keys": ["PV = nRT with R = 8.314 J/mol K.", "Dalton: partial pressures sum to total.", "Graham: effusion rate proportional to 1/sqrt(M).", "Ideal at low P, high T.", "Unit conversion first - always."], "reqs": ["Temperature in kelvin.", "Consistent pressure/volume units.", "Mole amounts."], "stds": ["R = 8.314 J/mol·K (SI).", "STP defined as 1 bar, 273.15 K (IUPAC)."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA, Simon JD. Physical Chemistry. University Science; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Ideal gas: moles from P, V, T.\"\"\"\ndef moles(P_Pa, V_m3, T_K):\n    return P_Pa*V_m3/(8.314*T_K)\nprint(f\"  1 atm, 22.4 L, 273 K: {moles(101325, 0.0224, 273.15):.3f} mol\")\n"}, {"tier": "Foundations", "g": "Gases", "title": "Kinetic Molecular Theory", "desc": "Gases are molecules in random motion: pressure is bombardment of walls, temperature is average kinetic energy (½m⟨v²⟩ = 3/2 kT). Maxwell-Boltzmann distributes speeds - most probable, average, and rms speeds differing by known factors.\nThe theory derives the gas laws from mechanics and predicts transport: diffusion, effusion, viscosity, thermal conductivity - all from molecular collisions. Mean free path (~68 nm in air at STP) sets the scale between collisions.", "how": "Compute rms speed: v_rms = √(3RT/M). Apply Maxwell-Boltzmann for speed distributions at temperature T. Estimate mean free path λ = 1/(√2 π d² N/V). Use kinetic theory to rationalize Graham's law and diffusion coefficients.", "keys": ["Pressure = molecular bombardment; T = kinetic energy.", "Maxwell-Boltzmann distributes molecular speeds.", "v_rms = sqrt(3RT/M).", "Mean free path ~68 nm in air at STP.", "Derives gas laws and transport properties."], "reqs": ["Molecular mass and diameter.", "Temperature in kelvin.", "Number density."], "stds": ["Speeds in m/s.", "Boltzmann constant k = 1.381e-23 J/K."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA, Simon JD. Physical Chemistry. University Science; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"RMS speeds at 298 K.\"\"\"\ndef vrms(M_kg_mol, T=298.15):\n    return (3*8.314*T/M_kg_mol)**0.5\nfor name, M in [(\"H2\", 0.002016), (\"N2\", 0.028014), (\"O2\", 0.031999)]:\n    print(f\"  {name:3s}: {vrms(M):.0f} m/s\")\n"}, {"tier": "Foundations", "g": "Gases", "title": "Real Gases and van der Waals", "desc": "Real gases deviate: molecules have volume (excluded) and attract each other. Van der Waals added both: (P + a(n/V)²)(V - nb) = nRT, with a for attraction, b for size. CO2's large a shows strong attraction; helium's tiny a and b show why it is nearly ideal.\nThe compressibility factor Z = PV/nRT measures deviation (Z = 1 ideal). Below the Boyle temperature attraction dominates (Z < 1); above, size dominates (Z > 1). At the critical point, liquid and gas merge - the van der Waals equation predicts it qualitatively.", "how": "Fit or look up a and b; solve the cubic for V at given P, T (or use Z charts). Compute Z to gauge deviation. Find critical constants from a, b (Tc = 8a/27Rb). Use corresponding-states for estimates when data is missing.", "keys": ["a corrects for attraction; b for molecular volume.", "Z = PV/nRT gauges deviation from ideal.", "Boyle temperature: Z = 1 over a range.", "Critical point where liquid-gas merge.", "He nearly ideal; CO2 strongly non-ideal."], "reqs": ["van der Waals a, b constants.", "Critical constants for checks.", "Pressure/temperature regime."], "stds": ["a in Pa·m⁶/mol², b in m³/mol.", "Z dimensionless."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "van der Waals JD. Doctoral dissertation, Leiden; 1873."], "demo": "#!/usr/bin/env python3\n\"\"\"Compressibility factor Z.\"\"\"\ndef Z(P, V, n, T):\n    return P*V/(n*8.314*T)\nprint(f\"  N2 at 100 atm (deviating): Z = {Z(100*101325, 0.00020, 1.0, 298):.2f} (< 1, attraction wins)\")\n"}, {"tier": "Foundations", "g": "Thermodynamics", "title": "The First Law of Thermodynamics", "desc": "Energy is conserved: ΔU = q + w - the change in internal energy equals heat added plus work done on the system. (Chemistry sign convention: work done BY the system is negative.) First law forbids free energy; it says nothing about direction.\nU is a state function - path independent - while q and w are path dependent. Enthalpy H = U + PV is the heat at constant pressure - the chemist's everyday energy, measured in calorimeters.", "how": "Bookkeep energy: identify heat and work flows with correct signs. Use state functions (U, H) for path-independent changes via Hess's law. Measure ΔH in calorimeters (bomb for ΔU, coffee-cup for ΔH). Compute PV work for expansions: w = -∫P dV.", "keys": ["ΔU = q + w: energy conserved.", "U and H are state functions; q and w are path-dependent.", "H = U + PV: heat at constant pressure.", "Calorimetry measures ΔH directly.", "First law: no free energy; silent on direction."], "reqs": ["System/surroundings boundary.", "Sign convention stated.", "Path specification for q, w."], "stds": ["Chemistry sign convention (work by system negative).", "Energies in kJ/mol."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA, Simon JD. Physical Chemistry. University Science; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"First-law bookkeeping.\"\"\"\nq, w = 500, -200  # J: heat in, work by system\nprint(f\"  q={q} J, w={w} J -> ΔU = {q+w} J\")\n"}, {"tier": "Foundations", "g": "Thermodynamics", "title": "Enthalpy and Thermochemistry", "desc": "Standard enthalpies of formation (ΔHf°, elements in standard states = 0) let any reaction's ΔH° be computed: ΣΔHf°(products) - ΣΔHf°(reactants) - Hess's law in action. Bond enthalpies estimate it from bonds broken minus bonds formed.\nCalorimetry measures directly: bomb calorimeters (constant V, ΔU) for combustion, solution calorimeters for ΔH. Exothermic (ΔH < 0) releases heat; endothermic absorbs. Kirchhoff's law adjusts ΔH for temperature via heat capacities.", "how": "Compute ΔH° from formation enthalpies with correct stoichiometry. Estimate with mean bond enthalpies when data is missing. Measure by calorimetry with calibration (electrical or standard reaction). Adjust for temperature with Kirchhoff: ΔH(T2) = ΔH(T1) + ∫ΔCp dT.", "keys": ["ΔH° from ΣΔHf°(products) - ΣΔHf°(reactants).", "Bond enthalpies: broken minus formed.", "Exothermic ΔH<0; endothermic ΔH>0.", "Bomb calorimeter: ΔU; solution: ΔH.", "Kirchhoff adjusts ΔH for temperature."], "reqs": ["Standard-state formation data.", "Balanced equation.", "Calorimeter calibration."], "stds": ["ΔHf° at 298.15 K, 1 bar.", "Enthalpies in kJ/mol."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Cox JD, Wagman DD, Medvedev VA. CODATA Key Values. Hemisphere; 1989."], "demo": "#!/usr/bin/env python3\n\"\"\"ΔH° of methane combustion from formation enthalpies.\"\"\"\ndHf = {\"CH4\": -74.8, \"O2\": 0, \"CO2\": -393.5, \"H2O\": -285.8}\ndH = (dHf[\"CO2\"] + 2*dHf[\"H2O\"]) - (dHf[\"CH4\"] + 2*dHf[\"O2\"])\nprint(f\"  CH4 + 2O2 -> CO2 + 2H2O: ΔH° = {dH:.1f} kJ/mol\")\n"}, {"tier": "Foundations", "g": "Thermodynamics", "title": "The Second Law and Entropy", "desc": "Entropy measures dispersal of energy: ΔS_universe ≥ 0, with equality only for reversible change. Spontaneous processes increase total entropy - the arrow of time. The second law forbids 100% heat-to-work conversion; Carnot efficiency (1 - Tc/Th) is the ceiling.\nStatistical meaning: S = k ln W - entropy counts microstates. Ordered crystals at 0 K have S = 0 (third law); gases have large S. Reactions increasing gas moles usually gain entropy.", "how": "Compute ΔS° from standard molar entropies (products - reactants). Check spontaneity via ΔS_total = ΔS_sys + ΔS_surr > 0, or via Gibbs energy. Estimate sign: more gas moles, more disorder → ΔS > 0. Apply Carnot limit to any heat engine claim.", "keys": ["ΔS_universe ≥ 0: the direction law.", "S = k ln W: entropy counts microstates.", "Carnot efficiency caps heat engines.", "Third law: perfect crystal at 0 K has S = 0.", "More gas moles usually means ΔS > 0."], "reqs": ["Standard molar entropies.", "Reversibility assessment.", "Temperature for ΔS_surr = -ΔH/T."], "stds": ["S° in J/mol·K at 298.15 K.", "Carnot efficiency as fraction."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Boltzmann L. Wien Ber 1877;76:373-435."], "demo": "#!/usr/bin/env python3\n\"\"\"Carnot efficiency limit.\"\"\"\ndef carnot(Tc, Th):\n    return 1 - Tc/Th\nprint(f\"  steam plant 800K/300K: max {carnot(300, 800)*100:.1f}% efficient\")\n"}, {"tier": "Foundations", "g": "Thermodynamics", "title": "Gibbs Energy: The Spontaneity Criterion", "desc": "G = H - TS combines the laws: at constant T and P, ΔG < 0 means spontaneous, ΔG = 0 equilibrium, ΔG > 0 forbidden. ΔG° = -RT ln K ties energy to the equilibrium constant - the most-used equation in chemistry.\nΔG = ΔH - TΔS shows the tug-of-war: exothermic, entropy-increasing reactions are spontaneous at all T; endothermic, entropy-decreasing never are; the mixed cases switch at T = ΔH/ΔS. Coupling (ATP hydrolysis) drives unfavorable reactions.", "how": "Compute ΔG° = ΔH° - TΔS°, then K = e^(-ΔG°/RT). Classify by signs: (-,-) always spontaneous; (+,+) never; mixed switch at ΔH/ΔS. For nonstandard conditions use ΔG = ΔG° + RT ln Q. Couple unfavorable steps to favorable ones (ATP) to drive them.", "keys": ["ΔG < 0 spontaneous; = 0 equilibrium; > 0 forbidden.", "ΔG° = -RT ln K: energy to equilibrium.", "ΔG = ΔH - TΔS: the tug-of-war.", "Mixed sign cases switch at T = ΔH/ΔS.", "Coupling to ATP drives uphill reactions."], "reqs": ["ΔH° and ΔS° (or ΔGf°).", "Temperature.", "Reaction quotient Q for nonstandard."], "stds": ["ΔG° at 298.15 K, 1 bar standard state.", "K dimensionless (activities)."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Gibbs JW. Trans Conn Acad 1876;3:108-248."], "demo": "#!/usr/bin/env python3\n\"\"\"K from ΔG°.\"\"\"\nimport math\ndef K(dG_kJ, T=298.15):\n    return math.exp(-dG_kJ*1000/(8.314*T))\nfor dG in (-30, 0, +30):\n    print(f\"  ΔG°={dG:+d} kJ/mol: K = {K(dG):.2e}\")\n"}, {"tier": "Foundations", "g": "Equilibrium", "title": "Chemical Equilibrium Basics", "desc": "At equilibrium, forward and reverse rates match - dynamic, not static. The equilibrium constant K = Πa(products)^ν/Πa(reactants)^ν (activities) is fixed at a given T; Q vs K predicts direction (Q < K → forward).\nLe Chatelier: disturb equilibrium and it shifts to oppose - add reactant, shift right; raise T, shift toward the endothermic side (van't Hoff). Catalysts speed both directions equally - they never move K.", "how": "Write K with activities (gases: P/bar; solutes: c/c°; pure solids/liquids omitted). Compare Q to K for direction. Apply Le Chatelier qualitatively; van't Hoff (ln K vs 1/T slope = -ΔH°/R) quantitatively. Solve equilibrium with ICE tables.", "keys": ["Equilibrium is dynamic: rates match.", "Q < K → forward; Q > K → reverse.", "Le Chatelier: systems oppose disturbances.", "van't Hoff: K(T) from ΔH°.", "Catalysts never change K."], "reqs": ["Balanced equation.", "Activities (standard states).", "Temperature."], "stds": ["K dimensionless via activities.", "van't Hoff plot: ln K vs 1/T."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "van't Hoff JH. Etudes de dynamique chimique. 1884."], "demo": "#!/usr/bin/env python3\n\"\"\"Q vs K direction predictor.\"\"\"\ndef direction(Q, K):\n    return \"shifts right (forward)\" if Q < K else (\"at equilibrium\" if Q == K else \"shifts left (reverse)\")\nprint(f\"  Q=0.1, K=10: {direction(0.1, 10)}\")\nprint(f\"  Q=50, K=10: {direction(50, 10)}\")\n"}, {"tier": "Foundations", "g": "Phases", "title": "Phase Equilibria: One Component", "desc": "Phase diagrams map solid/liquid/gas vs P and T: the water diagram's lines are coexistence curves (Clapeyron: dP/dT = ΔH/TΔV), meeting at the triple point (0.01 °C, 611 Pa) and ending at the critical point (374 °C, 221 bar) - beyond which liquid and gas merge into a supercritical fluid.\nThe phase rule F = C - P + 2 counts degrees of freedom: one component, two phases → one degree (move along the line). Supercritical CO2 extracts decaf coffee and dry-cleans - tunable solvent power.", "how": "Read the diagram: regions are single phases, lines are coexistence, triple point all three. Apply the phase rule to count freedoms. Use Clapeyron to predict how melting/boiling shifts with pressure (ice melts under pressure - negative slope, rare). Exploit supercritical fluids for extraction.", "keys": ["Triple point: all three phases coexist.", "Critical point: liquid-gas distinction vanishes.", "Phase rule F = C - P + 2.", "Clapeyron: coexistence-curve slopes.", "Supercritical CO2: tunable green solvent."], "reqs": ["P-T phase diagram.", "ΔH and ΔV for transitions.", "Component count."], "stds": ["Triple-point data cited.", "Clapeyron with consistent units."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Gibbs JW. Trans Conn Acad 1876;3:108-248."], "demo": "#!/usr/bin/env python3\n\"\"\"Phase rule: degrees of freedom.\"\"\"\ndef F(C, P):\n    return C - P + 2\nprint(f\"  water, liquid+gas: F = {F(1, 2)} (move along boiling curve)\")\nprint(f\"  water, triple point: F = {F(1, 3)} (fixed point)\")\n"}, {"tier": "Foundations", "g": "Phases", "title": "Solutions and Colligative Properties", "desc": "Dissolving: ΔG_mix usually negative (entropy wins). Ideal solutions obey Raoult's law (P_i = x_i P_i*); real ones deviate - positive (weaker unlike interactions) or negative (stronger, e.g., H-bonding in acetone-chloroform).\nColligative properties depend on particle count, not identity: vapor-pressure lowering, boiling-point elevation (ΔTb = Kb·m), freezing-point depression (ΔTf = Kf·m), osmosis (π = MRT). Antifreeze, de-icing salt, and desalination all run on them.", "how": "Test ideality with Raoult's law; fit deviations with activity coefficients. Compute colligative shifts with molality and van't Hoff factor i (NaCl: i≈2). Measure molar mass from freezing-point depression (cryoscopy) or osmotic pressure. Design separations from positive/negative deviations (azeotropes).", "keys": ["Colligative: depend on count, not identity.", "ΔTf = Kf·m·i; π = MRT.", "Raoult's law defines ideal solutions.", "Azeotropes: constant-boiling mixtures.", "Antifreeze and desalination use these."], "reqs": ["Molality and van't Hoff factor.", "Kf/Kb constants.", "Activity data for non-ideality."], "stds": ["Molality (mol/kg solvent).", "Osmotic pressure in Pa or atm."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA, Simon JD. Physical Chemistry. University Science; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Freezing-point depression: antifreeze.\"\"\"\nKf_water = 1.86\nm = 5.0  # molal ethylene glycol\nprint(f\"  ΔTf = {Kf_water*m:.1f} C -> freezes at {-Kf_water*m:.1f} C\")\n"}, {"tier": "Compounded", "g": "Phases", "title": "Multi-Component Phase Diagrams", "desc": "Two components add composition axes: temperature-composition diagrams for liquid-vapor (distillation - theoretical plates from the lens between bubble and dew curves) and solid-liquid (eutectics - the lowest-melting mixture, used in solder and casting).\nThe lever rule gives phase amounts from the diagram: fraction = opposite segment / total. Azeotropes (ethanol-water 95.6%) are extrema where liquid and vapor match - distillation cannot pass them. Partial miscibility adds liquid-liquid domes with upper/lower critical solution temperatures.", "how": "Read T-x diagrams: identify regions, azeotropes, eutectics. Apply the lever rule for phase quantities at any point. Design distillations from the bubble/dew lens (more plates for close boiling points); break azeotropes with entrainers or pressure swing.", "keys": ["T-x diagrams map boiling/melting vs composition.", "Lever rule: phase amounts from segment ratios.", "Eutectic: lowest-melting mixture.", "Azeotropes block simple distillation.", "Distillation plates from the bubble-dew lens."], "reqs": ["T-x or P-x diagram.", "Azeotrope/eutectic compositions.", "Activity data for non-ideality."], "stds": ["Compositions as mole fractions.", "Azeotropes with T and composition."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Smith JM et al. Introduction to Chemical Engineering Thermodynamics. 8th ed. McGraw-Hill; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Lever rule: fraction of liquid at a point.\"\"\"\ndef lever(x_overall, x_liq, x_vap):\n    return (x_vap - x_overall)/(x_vap - x_liq)\nprint(f\"  liquid fraction: {lever(0.4, 0.2, 0.7):.2f}\")\n"}, {"tier": "Compounded", "g": "Thermodynamics", "title": "Chemical Potential", "desc": "Chemical potential μ = (∂G/∂n)_{T,P} is the molar Gibbs energy - the driving force for matter flow, phase change, and reaction. Matter flows from high μ to low μ, just as heat flows hot to cold.\nFor ideal gases μ = μ° + RT ln(P/P°); for solutions μ = μ° + RT ln a. Equilibrium means equal μ across phases (μ_liquid = μ_vapor at boiling) and Σνμ = 0 for reactions - the compact statement of all equilibrium chemistry.", "how": "Write μ for each species with activities; set equal across phases at equilibrium. Derive K from Σνμ = 0. Use μ gradients to predict diffusion, osmosis, and electrochemical potentials (add zFφ for charged species).", "keys": ["μ = molar Gibbs energy; matter flows high→low.", "μ = μ° + RT ln a: the working form.", "Equal μ across phases at equilibrium.", "Σνμ = 0 is reaction equilibrium.", "Electrochemical potential adds zFφ."], "reqs": ["Activities of all species.", "Standard chemical potentials.", "Temperature and pressure."], "stds": ["μ in J/mol.", "Standard states specified."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Gibbs JW. Trans Conn Acad 1876;3:108-248."], "demo": "#!/usr/bin/env python3\n\"\"\"Chemical potential of an ideal gas vs pressure.\"\"\"\nimport math\ndef mu(mu0, P, P0=1.0, T=298.15):\n    return mu0 + 8.314*T*math.log(P/P0)/1000\nprint(f\"  μ - μ° at 10 bar: {mu(0, 10)-mu(0, 1):.2f} kJ/mol\")\n"}, {"tier": "Compounded", "g": "Thermodynamics", "title": "Activity and Non-Ideal Solutions", "desc": "Real solutions need activities (a = γx): the activity coefficient γ measures deviation from ideality. Debye-Hückel predicts γ for dilute electrolytes from ionic strength (log γ ∝ -z²√I) - the long-range Coulomb effect.\nExcess functions (G^E, H^E, S^E) quantify non-ideality; regular-solution theory models it with one parameter. Colligative properties, cell potentials, and solubilities all use activities - concentrations are the approximation.", "how": "Compute ionic strength I = ½Σc_i z_i²; apply Debye-Hückel limiting law (dilute) or extended/Davies (moderate). Fit excess Gibbs models (Margules, Wilson, NRTL) to VLE data. Always use activities in K and Nernst expressions for accuracy.", "keys": ["a = γx: activity corrects concentration.", "Debye-Hückel: log γ from ionic strength.", "Excess functions quantify non-ideality.", "Concentrations are the approximation; activities the truth.", "Models: Margules, Wilson, NRTL."], "reqs": ["Ionic strength or composition data.", "Temperature.", "Model parameters fitted."], "stds": ["γ dimensionless; I in mol/L.", "Debye-Hückel constants at stated T."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Debye P, Hückel E. Phys Z 1923;24:185-206."], "demo": "#!/usr/bin/env python3\n\"\"\"Debye-Hückel limiting law.\"\"\"\nimport math\ndef gamma(z, I, A=0.509):\n    return 10**(-A*z*z*math.sqrt(I))\nprint(f\"  γ for 1:1 electrolyte, I=0.01: {gamma(1, 0.01):.3f}\")\nprint(f\"  γ for 2:2 electrolyte, I=0.01: {gamma(2, 0.01):.3f}\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Reaction Rates and Rate Laws", "desc": "Rate = -d[reactant]/dt, measured by concentration vs time. The rate law (rate = k[A]^m[B]^n) is experimental - orders m, n come from data, not stoichiometry. The method of initial rates varies one concentration at a time.\nRate constants carry the order's units (s⁻¹ first order; M⁻¹s⁻¹ second). Temperature dependence is Arrhenius; catalysts lower Ea without touching thermodynamics. Half-lives fingerprint order.", "how": "Determine orders by initial-rate experiments (log-log plots) or integrated laws. Extract k with correct units. Measure at several temperatures for Arrhenius parameters. Propose mechanisms consistent with the rate law - the slow step dominates.", "keys": ["Rate laws are experimental, not stoichiometric.", "Orders from initial-rate or integrated data.", "k units encode the overall order.", "Half-life pattern fingerprints order.", "Catalysts lower Ea only."], "reqs": ["Concentration vs time data.", "Temperature control.", "Isolation or initial-rate design."], "stds": ["k with order-consistent units.", "Rates in M/s."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Laidler KJ. Chemical Kinetics. 3rd ed. Harper & Row; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Order from initial rates (doubling [A]).\"\"\"\ndef order(r1, r2):\n    import math\n    return round(math.log(r2/r1)/math.log(2))\nprint(f\"  rate doubles when [A] doubles: order {order(1.0, 2.0)}\")\nprint(f\"  rate quadruples: order {order(1.0, 4.0)}\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Integrated Rate Laws", "desc": "Integrated laws give concentration vs time: first order ln[A] = ln[A]₀ - kt (half-life constant: t½ = ln2/k); second order 1/[A] = 1/[A]₀ + kt (t½ = 1/k[A]₀); zero order [A] = [A]₀ - kt. Plot the linear form - the straight line identifies the order.\nRadioactive decay is first order (t½ characteristic per isotope); most elementary bimolecular steps are second order. Pseudo-first-order conditions (one reactant in excess) simplify kinetics.", "how": "Plot ln[A], 1/[A], and [A] vs t - the linear one wins. Extract k from slope. Use half-life patterns as a check (constant = first order). Apply pseudo-first-order with ≥10-fold excess of one reagent.", "keys": ["First: ln[A] linear, t½ constant.", "Second: 1/[A] linear, t½ ∝ 1/[A]₀.", "Zero: [A] linear.", "Linearized plots identify order.", "Pseudo-first-order simplifies with excess reagent."], "reqs": ["[A] vs t data over ≥2 half-lives.", "Temperature control.", "Excess-reagent condition if pseudo."], "stds": ["k with units; t½ with conditions.", "Linear-fit R² reported."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Laidler KJ. Chemical Kinetics. 3rd ed. Harper & Row; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Half-lives by order.\"\"\"\nimport math\nk = 0.1\nprint(f\"  1st order: t½ = {math.log(2)/k:.2f} s (constant)\")\nprint(f\"  2nd order, [A]0=1M: t½ = {1/(k*1):.1f} s; [A]0=2M: {1/(k*2):.1f} s\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Reaction Mechanisms and Rate-Determining Steps", "desc": "Mechanisms are elementary-step sequences summing to the overall reaction. The rate-determining step (slowest) controls the rate law: a slow first step gives rate = k[reactants]; a fast pre-equilibrium followed by a slow step gives the equilibrium constant times the slow-step rate.\nSteady-state approximation handles reactive intermediates (set d[I]/dt = 0). Mechanisms are never proven - only consistent with data (kinetics, isotope effects, stereochemistry, detected intermediates).", "how": "Propose elementary steps (unimolecular/bimolecular only). Apply pre-equilibrium or steady-state to eliminate intermediates. Match the derived law to experiment; test with isotope effects (kH/kD ~ 2-7 for H-transfer in the slow step) and intermediate trapping.", "keys": ["Slow step controls the rate law.", "Pre-equilibrium: K_eq × k_slow.", "Steady-state for reactive intermediates.", "Elementary steps are uni- or bimolecular.", "Mechanisms are consistent-with, never proven."], "reqs": ["Experimental rate law.", "Proposed elementary steps.", "Intermediate evidence."], "stds": ["Steps balanced atomically and in charge.", "kH/kD reported for isotope tests."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Espenson JH. Chemical Kinetics and Reaction Mechanisms. 2nd ed. McGraw-Hill; 1995."], "demo": "#!/usr/bin/env python3\n\"\"\"Pre-equilibrium rate law: A ⇌ I (K), I -> P (k2).\"\"\"\nK, k2 = 0.5, 0.1\nA = 1.0\nprint(f\"  rate = K*k2*[A] = {K*k2*A:.3f} M/s\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Temperature Dependence: Arrhenius", "desc": "k = A·e^(-Ea/RT): the Arrhenius equation. Ea is the barrier height; A the attempt frequency (collision/orientation). A 10 K rise roughly doubles many rates near room temperature - the rule of thumb from Ea ~ 50 kJ/mol.\nPlot ln k vs 1/T: slope = -Ea/R, intercept = ln A. Curved Arrhenius plots reveal tunneling (low T) or mechanism change. Food spoilage, drug shelf life, and materials aging all follow Arrhenius - accelerated aging tests extrapolate from high T.", "how": "Measure k at ≥4 temperatures spanning ≥30 K. Plot ln k vs 1/T; extract Ea and A with uncertainties. Check linearity - curvature means tunneling or competing paths. Extrapolate shelf life cautiously (mechanism must not change).", "keys": ["k = A·e^(-Ea/RT).", "ln k vs 1/T: slope gives Ea.", "~2× per 10 K near room T (typical Ea).", "Curvature signals tunneling or new mechanism.", "Accelerated aging extrapolates via Arrhenius."], "reqs": ["k at ≥4 temperatures.", "Temperature range ≥30 K.", "Mechanism constancy check."], "stds": ["Ea in kJ/mol; A with units of k.", "R² of Arrhenius fit."], "cites": ["Arrhenius S. Z Phys Chem 1889;4:226-248.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Rate ratio for a 10 K rise (Ea = 50 kJ/mol).\"\"\"\nimport math\ndef ratio(Ea_kJ, T1, T2):\n    return math.exp(-Ea_kJ*1000/8.314*(1/T2 - 1/T1))\nprint(f\"  298 -> 308 K: k ratio = {ratio(50, 298, 308):.2f}\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Catalysis: Homogeneous and Heterogeneous", "desc": "Catalysts provide alternative paths with lower Ea - speeding forward and reverse equally, never shifting equilibrium. Homogeneous (same phase: acids, organometallics) offers tunability; heterogeneous (surfaces: Pt, zeolites, Fe) offers separation.\nEnzymes are the masters: 10^6-10^17 rate enhancements via transition-state stabilization (Pauling). Catalytic converters (Pt/Rh/Pd), Haber-Bosch Fe, and Ziegler-Natta polymerization run civilization on catalysis - 90% of chemical products touch a catalyst.", "how": "Compare catalyzed vs uncatalyzed Ea from Arrhenius plots. For heterogeneous: consider adsorption (Langmuir isotherm), surface reaction, desorption - the Langmuir-Hinshelwood sequence. Measure turnover frequency (per site per time); watch for poisoning and deactivation.", "keys": ["Lower Ea, same equilibrium.", "Homogeneous: tunable; heterogeneous: separable.", "Enzymes: ultimate transition-state stabilizers.", "Langmuir-Hinshelwood for surface reactions.", "~90% of chemical products involve catalysis."], "reqs": ["Catalyzed and uncatalyzed rates.", "Active-site count for TOF.", "Deactivation/poisoning check."], "stds": ["TOF in s⁻¹ per site.", "Ea with and without catalyst."], "cites": ["Ertl G. Angew Chem 2008;47:3524-3535.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Catalytic rate enhancement from ΔEa.\"\"\"\nimport math\ndef enhancement(dEa_kJ, T=298.15):\n    return math.exp(dEa_kJ*1000/(8.314*T))\nprint(f\"  ΔEa = 20 kJ/mol: {enhancement(20):.0f}x faster\")\n"}, {"tier": "Compounded", "g": "Quantum", "title": "Quantum Mechanics: Origins", "desc": "Classical physics failed at small scales: blackbody radiation (Planck's quanta, 1900), the photoelectric effect (Einstein's photons, 1905), atomic spectra (Bohr's orbits, 1913), electron diffraction (de Broglie, 1924). Each crack admitted quantization.\nHeisenberg's uncertainty (Δx·Δp ≥ ħ/2) is not measurement clumsiness - it is nature: conjugate observables lack simultaneous sharp values. Operators replace variables; measurement collapses superpositions to eigenvalues.", "how": "Identify the quantum signature: discrete spectra, tunneling, zero-point energy. Apply de Broglie λ = h/p to estimate when wave effects matter (electrons: yes; baseballs: no). Use uncertainty to estimate ground-state energies (confine a particle → momentum spread → kinetic energy).", "keys": ["Planck, Einstein, Bohr, de Broglie: the founders.", "Quantization resolved the classical failures.", "Uncertainty is ontological, not instrumental.", "Operators and eigenvalues replace trajectories.", "de Broglie λ = h/p sets the quantum scale."], "reqs": ["System size vs de Broglie wavelength.", "Observable pair for uncertainty.", "Boundary conditions."], "stds": ["ħ = 1.055e-34 J·s.", "Energies in J or eV."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "McQuarrie DA. Quantum Chemistry. 2nd ed. University Science; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"de Broglie wavelengths.\"\"\"\ndef lam(m_kg, v):\n    return 6.626e-34/(m_kg*v)\nprint(f\"  electron at 1e6 m/s: {lam(9.11e-31, 1e6)*1e9:.2f} nm\")\nprint(f\"  baseball 0.15 kg at 40 m/s: {lam(0.15, 40):.2e} m\")\n"}, {"tier": "Compounded", "g": "Quantum", "title": "The Schrödinger Equation and Particle in a Box", "desc": "Ĥψ = Eψ: the time-independent Schrödinger equation. The Hamiltonian operator encodes kinetic + potential energy; wavefunctions ψ give probabilities (|ψ|²); boundary conditions quantize E. Particle in a 1D box: E_n = n²h²/8mL² - quantization from confinement alone.\nThe model explains conjugated dyes: longer boxes (more double bonds) absorb at longer wavelengths (particle-in-a-box predicts cyanine dye colors). Zero-point energy (n = 1, E > 0) is pure quantum - no classical analogue.", "how": "Write Ĥ = T + V for the system; apply boundary conditions (ψ = 0 at walls). Solve for allowed E_n and ψ_n; normalize. Estimate conjugated-system absorptions from box length (chain length); compute zero-point energies for confined particles.", "keys": ["Ĥψ = Eψ; |ψ|² is probability.", "Confinement alone quantizes energy.", "E_n = n²h²/8mL² for the 1D box.", "Explains dye colors vs chain length.", "Zero-point energy has no classical analogue."], "reqs": ["Hamiltonian (T + V).", "Boundary conditions.", "Normalization."], "stds": ["Energies in J or eV.", "Wavefunctions normalized to 1."], "cites": ["Schrödinger E. Ann Phys 1926;79:361-376.", "McQuarrie DA. Quantum Chemistry. 2nd ed. University Science; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Particle-in-a-box levels.\"\"\"\ndef E(n, L_nm, m=9.11e-31):\n    h = 6.626e-34\n    return n*n*h*h/(8*m*(L_nm*1e-9)**2)/1.602e-19\nfor n in (1, 2, 3):\n    print(f\"  n={n}: E = {E(n, 1.0):.2f} eV (L=1 nm)\")\n"}, {"tier": "Compounded", "g": "Quantum", "title": "Atomic Structure: Orbitals", "desc": "Hydrogen's exact solution gives quantum numbers n, l, m_l (energy, shape, orientation) plus spin m_s. Orbitals: s spheres, p dumbbells, d cloverleafs - probability clouds, not orbits. Multi-electron atoms fill by Aufbau, Pauli, Hund: 1s²2s²2p⁶... with Cr/Cu exceptions.\nShielding and penetration order orbital energies (ns < (n-1)d < np); effective nuclear charge Z_eff explains periodic trends - radius shrinks across rows, ionization energy rises. Nodes count = n - 1.", "how": "Write configurations with the filling order; apply Hund's rule (max multiplicity) for degenerate orbitals. Estimate Z_eff with Slater's rules for trend rationalization. Count radial/angular nodes (n-l-1 radial, l angular) to sketch orbitals.", "keys": ["Quantum numbers n, l, m_l, m_s.", "Aufbau + Pauli + Hund fill orbitals.", "s/p/d shapes are probability clouds.", "Z_eff explains periodic trends.", "Nodes: n-1 total (n-l-1 radial)."], "reqs": ["Nuclear charge Z.", "Electron count.", "Filling-order exceptions noted."], "stds": ["Configurations per IUPAC notation.", "Z_eff dimensionless."], "cites": ["McQuarrie DA. Quantum Chemistry. 2nd ed. University Science; 2007.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Electron configuration builder (first 20).\"\"\"\norder = [\"1s\",\"2s\",\"2p\",\"3s\",\"3p\",\"4s\",\"3d\",\"4p\"]\ncap = {\"s\":2,\"p\":6,\"d\":10}\ndef config(Z):\n    out, z = [], Z\n    for o in order:\n        if z <= 0: break\n        n = min(cap[o[-1]], z); out.append(f\"{o}{n}\"); z -= n\n    return \" \".join(out)\nprint(\"  Fe (26):\", config(26))\n"}, {"tier": "Compounded", "g": "Quantum", "title": "Molecular Orbital Theory Basics", "desc": "LCAO: molecular orbitals are linear combinations of atomic orbitals - bonding (constructive), antibonding (destructive), nonbonding. Fill by Aufbau: bond order = (bonding e⁻ - antibonding e⁻)/2. H2 (order 1) is stable; He2 (order 0) does not exist.\nO2's paramagnetism (two unpaired π* electrons) is MO theory's triumph - valence-bond theory predicts diamagnetic. HOMO/LUMO control reactivity (frontier-orbital theory): donors give from HOMO, acceptors take into LUMO.", "how": "Build the MO diagram: order AOs by energy, combine same-symmetry pairs, fill with valence electrons. Compute bond order; predict magnetism. Identify HOMO/LUMO for reactivity (Fukui): electrophiles attack high HOMO density, nucleophiles high LUMO density.", "keys": ["LCAO builds MOs from atomic orbitals.", "Bond order = (bonding - antibonding)/2.", "O2 paramagnetism: the triumph.", "HOMO/LUMO govern reactivity.", "He2 does not exist (order 0)."], "reqs": ["Valence electron count.", "AO energy ordering.", "Symmetry matching."], "stds": ["Bond orders to 0.5.", "HOMO/LUMO energies in eV."], "cites": ["McQuarrie DA. Quantum Chemistry. 2nd ed. University Science; 2007.", "Fleming I. Molecular Orbitals and Organic Chemical Reactions. Wiley; 2009."], "demo": "#!/usr/bin/env python3\n\"\"\"Diatomic bond orders.\"\"\"\ndef bo(bonding, anti):\n    return (bonding-anti)/2\nfor name, b, a in [(\"H2\",2,0),(\"He2\",2,2),(\"N2\",10,4),(\"O2\",10,6)]:\n    print(f\"  {name:3s}: order {bo(b,a):.1f}\")\n"}, {"tier": "Advanced", "g": "Statistical", "title": "Statistical Thermodynamics: Boltzmann", "desc": "Macroscopic thermodynamics emerges from molecular statistics: S = k ln W, where W counts microstates. The Boltzmann distribution (p_i ∝ e^(-ε_i/kT)) gives the most probable energy distribution - derived by maximizing W under fixed total energy.\nThis single distribution yields the barometric formula, Maxwell-Boltzmann speeds, and chemical equilibrium (with degeneracies and partition functions). Temperature itself is defined by 1/T = ∂S/∂U - statistics underwrites thermodynamics.", "how": "Count microstates combinatorially for model systems (Einstein solids, two-level systems). Maximize ln W with Lagrange multipliers to derive Boltzmann. Apply p_i = e^(-ε_i/kT)/q to populations, spectra (Boltzmann plots), and atmospheric profiles.", "keys": ["S = k ln W: entropy counts microstates.", "Boltzmann: p_i proportional to e^(-ε_i/kT).", "Derived by maximizing W at fixed energy.", "1/T = ∂S/∂U defines temperature.", "Yields barometric, MB, equilibrium results."], "reqs": ["Energy-level spectrum.", "Degeneracies.", "Fixed N, V (or U) constraints."], "stds": ["k = 1.381e-23 J/K.", "Populations as fractions."], "cites": ["Boltzmann L. Wien Ber 1877;76:373-435.", "McQuarrie DA. Statistical Mechanics. University Science; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"Boltzmann populations of a two-level system.\"\"\"\nimport math\ndef p_upper(dE_J, T):\n    return 1/(1+math.exp(dE_J/(1.381e-23*T)))\nprint(f\"  ΔE=kT: upper fraction = {p_upper(1.381e-23*300, 300):.3f}\")\n"}, {"tier": "Advanced", "g": "Statistical", "title": "Partition Functions", "desc": "The molecular partition function q = Σ g_i e^(-ε_i/kT) is the master key: U, S, A, C_V, and K all derive from it (A = -kT ln Q). It factorizes: q = q_trans · q_rot · q_vib · q_elec - each from its energy-level formula.\nTranslational q gives the Sackur-Tetrode entropy (absolute entropies of gases!); rotational q needs the characteristic temperature θ_rot; vibrational q freezes out below θ_vib (why heat capacities drop). Equilibrium constants are partition-function ratios.", "how": "Compute each factor: q_trans = V/Λ³ (thermal wavelength), q_rot = T/σθ_rot, q_vib = 1/(1-e^(-θ_vib/T)). Derive thermodynamics by differentiation (U = kT²∂lnq/∂T). Form K from molecular partition functions and Δε₀ - statistical prediction of equilibrium.", "keys": ["q = Σ g_i e^(-ε_i/kT): the master key.", "All thermodynamics derives from q.", "Factorizes: trans × rot × vib × elec.", "Sackur-Tetrode: absolute gas entropies.", "K is a partition-function ratio."], "reqs": ["Energy-level formulas per mode.", "Characteristic temperatures.", "Symmetry numbers."], "stds": ["q dimensionless.", "θ_rot, θ_vib in kelvin."], "cites": ["McQuarrie DA. Statistical Mechanics. University Science; 2000.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Rotational partition function of N2.\"\"\"\ndef q_rot(T, theta_rot=2.88, sigma=2):\n    return T/(sigma*theta_rot)\nprint(f\"  q_rot(N2, 298 K) = {q_rot(298):.1f}\")\n"}, {"tier": "Advanced", "g": "Kinetics", "title": "Transition State Theory", "desc": "Eyring's theory: reactants form an activated complex (transition state, ‡) in quasi-equilibrium, then cross at frequency kT/h. k = (kT/h)·e^(-ΔG‡/RT) = (kT/h)·e^(ΔS‡/R)·e^(-ΔH‡/RT) - splitting Ea into enthalpy and entropy of activation.\nΔS‡ diagnoses mechanism: negative (ordered TS, associative), positive (loose TS, dissociative). Primary kinetic isotope effects (kH/kD 2-7) flag H-transfer in the slow step. Tunneling corrections matter for light atoms at low T.", "how": "Get ΔH‡, ΔS‡ from Eyring plot (ln(k/T) vs 1/T). Interpret ΔS‡ sign for mechanism. Measure kH/kD for H-transfer tests. Compare computed (DFT) barriers to experimental ΔG‡ - agreement within ~2 kcal/mol is good.", "keys": ["k = (kT/h)·e^(-ΔG‡/RT).", "ΔS‡ sign diagnoses associative vs dissociative.", "kH/kD 2-7 flags H in the slow step.", "Activated complex in quasi-equilibrium.", "Tunneling matters for H at low T."], "reqs": ["k vs T data.", "Isotope-effect measurements.", "Computed barriers for comparison."], "stds": ["ΔH‡, ΔS‡, ΔG‡ with T stated.", "kH/kD dimensionless."], "cites": ["Eyring H. J Chem Phys 1935;3:107-115.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Eyring rate from ΔG‡.\"\"\"\nimport math\ndef k_eyring(dG_kJ, T=298.15):\n    return 1.381e-23*T/6.626e-34*math.exp(-dG_kJ*1000/(8.314*T))\nprint(f\"  ΔG‡=75 kJ/mol: k = {k_eyring(75):.2e} s⁻¹\")\n"}, {"tier": "Advanced", "g": "Kinetics", "title": "Photochemistry", "desc": "Light drives chemistry: absorption creates excited states (singlet/triplet), which react, emit (fluorescence/phosphorescence), or decay non-radiatively (Jablonski diagram). Stark-Einstein: one photon per molecule - quantum yield φ measures efficiency.\nSelection rules differ from thermal (orbital symmetry inverts); photosynthesis, vision (retinal isomerization), and photolithography run on photochemistry. Ozone photolysis (Chapman cycle) shields Earth; CFC photolysis destroyed it - Rowland and Molina, Nobel 1995.", "how": "Map the Jablonski diagram: absorption, internal conversion, intersystem crossing, emission. Measure quantum yields with chemical actinometers. Distinguish singlet (fast, fluorescent) from triplet (slow, phosphorescent, O2-quenched) reactivity. Design photoreactors with wavelength-matched sources.", "keys": ["One photon per molecule (Stark-Einstein).", "Quantum yield φ measures efficiency.", "Jablonski diagram maps excited-state fates.", "Photochemical selection rules invert thermal ones.", "Vision, photosynthesis, lithography: applied photochemistry."], "reqs": ["Absorption spectrum of reactant.", "Light intensity (actinometry).", "O2 control for triplets."], "stds": ["φ dimensionless (molecules/photon).", "Wavelengths in nm."], "cites": ["Turro NJ et al. Modern Molecular Photochemistry. University Science; 2010.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Photon energy and moles of photons.\"\"\"\ndef E_photon(lam_nm):\n    return 6.626e-34*3e8/(lam_nm*1e-9)\nE = E_photon(500)\nprint(f\"  500 nm photon: {E/1.602e-19:.2f} eV = {E*6.022e23/1000:.0f} kJ/mol photons\")\n"}, {"tier": "Advanced", "g": "Interfaces", "title": "Surface Chemistry and Adsorption", "desc": "Surfaces are where heterogeneous catalysis, corrosion, and adhesion happen. Adsorption isotherms quantify coverage: Langmuir (monolayer, θ = KP/(1+KP)), BET (multilayer - the surface-area standard), Freundlich (empirical).\nSurface techniques (XPS, AES, STM, LEED) see the top atomic layers; Langmuir (Nobel 1932) founded the field. Surfactants self-assemble at interfaces - micelles above the CMC - enabling detergency and emulsions.", "how": "Measure isotherms (volumetric/gravimetric); fit Langmuir for chemisorption, BET for surface area (N2 at 77 K). Characterize surfaces with XPS (composition) and STM (atomic imaging). Formulate surfactants above the CMC for detergency; use contact angles for wettability.", "keys": ["Langmuir: monolayer; BET: multilayer/surface area.", "Surfaces host catalysis, corrosion, adhesion.", "XPS/STM see atomic layers.", "Micelles form above the CMC.", "Contact angles measure wettability."], "reqs": ["Adsorption isotherm data.", "Surface-area standard procedure.", "Clean-surface preparation."], "stds": ["BET area in m²/g.", "Coverage θ dimensionless."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Somorjai GA, Li Y. Introduction to Surface Chemistry. 2nd ed. Wiley; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Langmuir coverage vs pressure.\"\"\"\ndef theta(K, P):\n    return K*P/(1+K*P)\nfor P in (0.1, 1.0, 10.0):\n    print(f\"  P={P:4.1f}: θ = {theta(2.0, P):.3f}\")\n"}, {"tier": "Advanced", "g": "Interfaces", "title": "Colloids and Interfaces", "desc": "Colloids (1 nm - 1 µm particles) live between solutions and suspensions: milk, fog, ink, blood. Brownian motion, Tyndall scattering, and huge surface areas define them. Stability is DLVO theory: van der Waals attraction vs double-layer repulsion - salt collapses the double layer (Schulze-Hardy rule: higher valence coagulates faster).\nEmulsions, foams, and aerosols are colloidal systems; zeta potential predicts stability (|ζ| > 30 mV stable). Nanoparticles are engineered colloids - quantum dots, drug carriers, catalysts.", "how": "Measure size by DLS, charge by zeta potential. Stabilize electrostatically (charge) or sterically (polymers). Formulate emulsions with HLB-matched surfactants. Predict coagulation with DLVO/Schulze-Hardy; test accelerated aging.", "keys": ["1 nm - 1 µm: the colloidal range.", "DLVO: attraction vs double-layer repulsion.", "Schulze-Hardy: valence rules coagulation.", "|zeta| > 30 mV predicts stability.", "Milk, fog, ink: everyday colloids."], "reqs": ["Particle-size distribution.", "Zeta potential.", "Ionic strength."], "stds": ["Sizes in nm; zeta in mV.", "CMC/HLB for surfactants."], "cites": ["Hiemenz PC, Rajagopalan R. Principles of Colloid and Surface Chemistry. 3rd ed. CRC; 1997.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Schulze-Hardy: critical coagulation concentration vs valence.\"\"\"\ndef ccc(z):\n    return 1/z**6\nfor z in (1, 2, 3):\n    print(f\"  z={z}: relative CCC = {ccc(z):.4f}\")\n"}, {"tier": "Advanced", "g": "Macromolecules", "title": "Macromolecules: Physical Chemistry of Polymers", "desc": "Polymer chains coil randomly: end-to-end distance scales as √N (freely jointed chain), measured by light scattering and viscometry ([η] = KM^a, Mark-Houwink). Flory-Huggins theory gives the free energy of mixing - the χ parameter decides solubility.\nSolutions, melts, and glasses: Tg marks the glass transition (free-volume freezing), Tm the crystal melting. Viscoelasticity (Maxwell/Voigt models) bridges liquid and solid - time-temperature superposition (WLF) predicts long-term creep from short tests.", "how": "Determine MW by GPC (calibrated), light scattering (absolute), or viscometry. Measure Tg/Tm by DSC. Fit solution behavior with Flory-Huggins χ. Use WLF shifting for long-time mechanical predictions from short experiments.", "keys": ["Chains coil: size proportional to sqrt(N).", "Flory-Huggins χ decides polymer solubility.", "Tg: glass transition; Tm: crystal melting.", "Viscoelasticity bridges solid and liquid.", "WLF: time-temperature superposition."], "reqs": ["Molecular-weight distribution.", "Thermal transitions (DSC).", "Solvent interaction parameter."], "stds": ["Mn, Mw, dispersity.", "Tg/Tm in °C with method."], "cites": ["Flory PJ. Principles of Polymer Chemistry. Cornell; 1953.", "Rubinstein M, Colby RH. Polymer Physics. Oxford; 2003."], "demo": "#!/usr/bin/env python3\n\"\"\"Coil size scaling: R proportional to sqrt(N).\"\"\"\ndef Rg(N, b=1.0):\n    return b*(N/6)**0.5\nfor N in (100, 10000, 1000000):\n    print(f\"  N={N:7d}: Rg = {Rg(N):6.1f} segment lengths\")\n"}, {"tier": "Advanced", "g": "Solutions", "title": "Electrolyte Solutions: Debye-Hückel", "desc": "Ions in solution interact long-range: each ion's atmosphere of counterions lowers its activity (Debye-Hückel limiting law, log γ± = -A|z+z-|√I). Conductivity follows Kohlrausch (Λ = Λ° - K√c); strong electrolytes are fully dissociated - non-ideality, not association, causes the drop.\nBjerrum ion pairs form at high charge/small size; the Debye length (κ⁻¹ ~ 1 nm at 0.1 M) sets the atmosphere's thickness. Batteries, corrosion, and physiology all run on electrolyte non-ideality.", "how": "Compute I and γ± from Debye-Hückel (limiting < 0.01 M, extended/Davies to ~0.5 M). Correct cell potentials and solubilities with activities. Measure conductivity vs √c for Λ° (Kohlrausch). Watch for ion pairing in low-dielectric solvents.", "keys": ["Ion atmospheres lower activities.", "Limiting law: log γ from √I.", "Debye length ~1 nm at 0.1 M.", "Strong electrolytes: non-ideality, not association.", "Activities correct cells and solubilities."], "reqs": ["Concentrations and charges.", "Dielectric constant, temperature.", "Conductivity data for Λ°."], "stds": ["I in mol/L; κ⁻¹ in nm.", "Λ in S·cm²/mol."], "cites": ["Debye P, Hückel E. Phys Z 1923;24:185-206.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Ionic strength of mixed electrolytes.\"\"\"\ndef I(ions):\n    return 0.5*sum(c*z*z for c, z in ions)\nprint(f\"  0.1 M NaCl: I = {I([(0.1,1),(0.1,-1)]):.2f} M\")\nprint(f\"  0.1 M MgSO4: I = {I([(0.1,2),(0.1,-2)]):.2f} M\")\n"}, {"tier": "Advanced", "g": "Transport", "title": "Transport Properties: Diffusion, Viscosity", "desc": "Fick's laws describe diffusion (J = -D∇c); Stokes-Einstein (D = kT/6πηr) ties it to viscosity and size - the basis of DLS sizing. Viscosity (Newton: τ = ηγ̇) measures momentum transport; non-Newtonian fluids (ketchup, blood) break the linear law.\nThermal conductivity and electrical conductivity complete the transport set; the Wiedemann-Franz law ties thermal to electrical in metals. Membranes, chromatography, and drug delivery are applied transport.", "how": "Measure D by diaphragm cell, NMR, or DLS; η by viscometry (Ostwald, cone-plate). Apply Stokes-Einstein for hydrodynamic radii. Model non-Newtonian flow with power-law or Herschel-Bulkley. Design separations from D differences (dialysis, field-flow fractionation).", "keys": ["Fick: J = -D∇c.", "Stokes-Einstein: D from η and size.", "Newtonian: τ = ηγ̇; many fluids are not.", "Wiedemann-Franz ties thermal/electrical conduction.", "Transport underlies separations and delivery."], "reqs": ["Temperature and medium viscosity.", "Particle/molecular size.", "Concentration gradients."], "stds": ["D in m²/s; η in Pa·s.", "Shear rates in s⁻¹."], "cites": ["Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017.", "Bird RB et al. Transport Phenomena. 2nd ed. Wiley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Stokes-Einstein diffusion coefficient.\"\"\"\ndef D(T, eta, r_nm):\n    return 1.381e-23*T/(6*3.1416*eta*r_nm*1e-9)\nprint(f\"  1 nm particle in water, 298 K: D = {D(298, 1e-3, 1):.2e} m²/s\")\n"}, {"tier": "Advanced", "g": "Computational", "title": "Computational Chemistry Methods", "desc": "Computation predicts chemistry: Hartree-Fock (mean-field, exact exchange, no correlation), DFT (B3LYP, ωB97X-D - the workhorse, ~chemical accuracy for many properties), MP2/CCSD(T) (gold standard, expensive), semi-empirical (fast, parameterized).\nBasis sets (STO-3G to cc-pVQZ) expand orbitals; bigger is better-converged. Solvation (PCM/SMD), thermochemistry (frequencies → G), and transition-state searches make computation predictive - benchmark against experiment always.", "how": "Choose method by accuracy/cost: DFT for routine, CCSD(T) for benchmarks. Converge basis sets (cc-pVTZ usually enough). Optimize geometries, confirm minima (no imaginary frequencies) and TS (one imaginary). Add solvation and thermal corrections; benchmark key numbers.", "keys": ["HF: no correlation; DFT: the workhorse; CCSD(T): gold standard.", "Basis sets expand orbitals - converge them.", "Frequencies confirm minima vs transition states.", "Solvation models (PCM/SMD) for solution.", "Benchmark against experiment always."], "reqs": ["Method and basis set stated.", "Convergence criteria.", "Benchmark data."], "stds": ["Energies in hartrees or kJ/mol.", "Frequencies in cm⁻¹."], "cites": ["Jensen F. Introduction to Computational Chemistry. 3rd ed. Wiley; 2017.", "Cramer CJ. Essentials of Computational Chemistry. 2nd ed. Wiley; 2004."], "demo": "#!/usr/bin/env python3\n\"\"\"Method accuracy vs cost ladder.\"\"\"\nmethods = [(\"semi-empirical\", 1, 3), (\"DFT\", 3, 8), (\"MP2\", 5, 6), (\"CCSD(T)\", 8, 2)]\nfor name, acc, speed in sorted(methods, key=lambda m: -m[1]):\n    print(f\"  {name:14s}: accuracy {acc}/8, speed {speed}/8\")\n"}, {"tier": "Advanced", "g": "Kinetics", "title": "Femtochemistry and Ultrafast Dynamics", "desc": "Zewail's femtochemistry (Nobel 1999) watches bonds break in real time: femtosecond laser pulses (10⁻¹⁵ s) freeze transition states - NaI dissociation mapped as it happens. Pump-probe spectroscopy is the camera.\nAttosecond pulses (10⁻¹⁸ s) now track electrons themselves. Applications: vision's first 200 fs, photosynthetic energy transfer, proton transfer in GFP. Chemistry's fastest events are now observable - the transition state is no longer hypothetical.", "how": "Design pump-probe: pump initiates, delayed probe snapshots the evolution. Choose wavelengths for pump (initiate) and probe (detect intermediates). Analyze with global fitting of time-resolved spectra; assign time constants to elementary steps (IVR, IC, ISC, reaction).", "keys": ["Femtosecond pulses freeze bond breaking.", "Pump-probe: initiate, then snapshot.", "Zewail, Nobel 1999.", "Attoseconds now track electrons.", "Transition states directly observed."], "reqs": ["Femtosecond laser system.", "Pump/probe wavelength selection.", "Global kinetic analysis."], "stds": ["Time constants in fs/ps.", "Wavelengths in nm."], "cites": ["Zewail AH. J Phys Chem A 2000;104:5660-5694.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Timescales of molecular motion.\"\"\"\nscales = [(\"bond vibration\", \"10 fs\"), (\"transition state\", \"100 fs\"), (\"retinal isomerization\", \"200 fs\"), (\"fluorescence\", \"1 ns\")]\nfor name, t in scales:\n    print(f\"  {name:24s}: {t}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-PHYCHS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-PHYCHS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-physical-chemistry-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('physical-chemistry-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
